function nextNumber(kind){project.counters=project.counters||{};const list=kind==='subject'?project.subjects:project.assets.filter(a=>a.kind===kind);const n=Math.max(project.counters[kind]||0,0,...list.map(a=>a.number))+1;project.counters[kind]=n;return n;}
