  if(el.dataset.subject){editSubject(el.dataset.subject);return;}if(el.dataset.asset){editAsset(el.dataset.asset);return;}if(el.dataset.window&&!e.target.closest('[data-resize]')){selectWindow(el.dataset.window);return;}
