  if(el.dataset.insert){const target=lastField&&document.contains(lastField)?lastField:$('#field-detail');if(!target)return;const start=target.selectionStart||0,end=target.selectionEnd||0;checkpoint();target.setRangeText(el.dataset.insert,start,end,'end');current()[target.dataset.field]=target.value;changed(false);target.focus();renderStatus();return;}
  if(el.dataset.compiledToken){const [kind,num]=el.dataset.compiledToken.split(' ');if(kind==='Subject'){const s=project.subjects.find(s=>s.number===Number(num));if(s)editSubject(s.id);}else{const w=current(),ref=H3.refMap(project,w,project.windows.indexOf(w)).find(a=>a.token===`<${el.dataset.compiledToken}>`);if(ref)editAsset(ref.id);else toast('This token is the previous window’s generated continuity anchor, not an uploaded file.');}return;}
