  if(el.dataset.deleteSubject){if(await askConfirm('Remove this subject from the project? Existing text tokens will be flagged for review.')){mutate(()=>{project.subjects=project.subjects.filter(s=>s.id!==el.dataset.deleteSubject);project.windows.forEach(w=>{w.subjectIds=w.subjectIds.filter(id=>id!==el.dataset.deleteSubject);if(w.casting)delete w.casting[el.dataset.deleteSubject];});});closeDialog();}return;}
