let reorderId=null;$('#timeline').addEventListener('dragstart',e=>{const el=e.target.closest('[data-reorder]');if(el){reorderId=el.dataset.reorder;e.dataTransfer.setData('text/plain',reorderId);e.dataTransfer.effectAllowed='move';}});$('#timeline').addEventListener('dragover',e=>{if(reorderId)e.preventDefault();});$('#timeline').addEventListener('drop',e=>{if(!reorderId)return;e.preventDefault();const target=e.target.closest('[data-window]');if(target)reorderWindow(reorderId,project.windows.findIndex(w=>w.id===target.dataset.window));reorderId=null;});$('#timeline').addEventListener('dragend',()=>reorderId=null);
